// Recolectar métricas de Prometheus (instant query)
const fs = require('fs');
const { execSync } = require('child_process');
const BASE = 'http://host.docker.internal:9090/api/v1/query';

function readEnv(key) {
  try {
    const raw = fs.readFileSync('/proc/1/environ', 'latin1');
    const m = raw.split('\0').find(l => l.startsWith(key + '='));
    return m ? m.slice(key.length + 1) : null;
  } catch (e) { return null; }
}
const nextcloudUrl = readEnv('NEXTCLOUD_URL');
const nextcloudConfigured = !!nextcloudUrl;

function prom(q) {
  const url = BASE + '?query=' + encodeURIComponent(q);
  const out = execSync('wget -qO- "' + url + '"', { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 10 * 1024 * 1024 });
  try {
    const j = JSON.parse(out);
    if (j.status !== 'success') return { value: null, error: j.error || 'query failed' };
    const r = (j.data && j.data.result && j.data.result[0]) ? j.data.result[0] : null;
    return { value: r && r.value ? parseFloat(r.value[1]) : null };
  } catch (e) { return { value: null, error: String(e.message || e) }; }
}

const m = {
  backend_up: prom('probe_success{job="blackbox_backend"}').value,
  backend_probe_duration_seconds: prom('probe_duration_seconds{job="blackbox_backend"}').value,
  backend_restart_count: prom('docker_container_restart_count{name="gymbro-backend"}').value,
  node_memory_MemAvailable_bytes: prom('node_memory_MemAvailable_bytes').value,
  node_memory_MemTotal_bytes: prom('node_memory_MemTotal_bytes').value
};

const ts = new Date().toISOString();
const stamp = ts.replace(/[:.]/g, '-').slice(0, 19);
const filename = 'informe-' + stamp + '.md';
const filepath = '/data/informes/' + filename;

const upStr = m.backend_up === null ? 'sin datos' : (m.backend_up === 1 ? 'UP' : 'DOWN');
const memFreeMB = m.node_memory_MemAvailable_bytes !== null ? Math.round(m.node_memory_MemAvailable_bytes / 1024 / 1024) : null;
const memTotalMB = m.node_memory_MemTotal_bytes !== null ? Math.round(m.node_memory_MemTotal_bytes / 1024 / 1024) : null;

return [{ json: {
  metrics: m,
  backendUpStr: upStr,
  memFreeMB,
  memTotalMB,
  startedAt: ts,
  filename,
  filepath,
  nextcloudConfigured,
  nextcloudUrl
} }];

// Llamar al analizador Python via POST (servicio informe-analyzer:8090)
const fs = require('fs');
const { execSync } = require('child_process');
const prev = $input.item.json;

const tmpPath = '/tmp/informe-payload.json';
fs.writeFileSync(tmpPath, JSON.stringify({ metrics: prev.metrics }));

let analysis = { anomalies: [], riskLevel: 'UNKNOWN', summary: 'Analizador no respondió' };
try {
  const out = execSync('wget -qO- --header="Content-Type: application/json" --post-file="' + tmpPath + '" http://informe-analyzer:8090/analyze',
    { encoding: 'utf8', shell: '/bin/sh', maxBuffer: 1024 * 1024 });
  analysis = JSON.parse(out);
} catch (e) {
  analysis = { anomalies: [], riskLevel: 'UNKNOWN', summary: 'Error analizador: ' + String(e.message || e) };
}

return [{ json: Object.assign({}, prev, { analysis }) }];

// Subir informe a Nextcloud (WebDAV PUT con Basic Auth)
const fs = require('fs');
const http = require('http');
const p = $input.item.json;

function readEnv(key) {
  try {
    const raw = fs.readFileSync('/proc/1/environ', 'latin1');
    const m = raw.split('\0').find(l => l.startsWith(key + '='));
    return m ? m.slice(key.length + 1) : null;
  } catch (e) { return null; }
}

const ncUrl  = readEnv('NEXTCLOUD_URL');
const ncUser = readEnv('NEXTCLOUD_USER');
const ncPass = readEnv('NEXTCLOUD_PASSWORD');
if (!ncUrl || !ncUser || !ncPass) {
  return [{ json: { ...p, nextcloudUploaded: false, nextcloudError: 'NEXTCLOUD_* no configurado en .env' } }];
}
if (!fs.existsSync(p.filepath)) {
  return [{ json: { ...p, nextcloudUploaded: false, nextcloudError: 'Informe local no existe: ' + p.filepath } }];
}

const target = ncUrl.replace(/\/$/, '') + '/SmartGymBro-TP-Final/05-Monitoreo-y-Automatizacion/' + p.filename;
const body   = fs.readFileSync(p.filepath, 'utf8');
const auth   = Buffer.from(ncUser + ':' + ncPass).toString('base64');
const m      = /^(https?):\/\/([^\/:]+)(?::([0-9]+))?(.*)$/.exec(target);
if (!m) {
  return [{ json: { ...p, nextcloudUploaded: false, nextcloudError: 'target malformado: ' + target } }];
}
const hostname = m[2];
const port     = parseInt(m[3] || '80', 10);
const path     = (m[4] || '/') + (m[4] && m[4].includes('?') ? '' : '');

return new Promise((resolve) => {
  const req = http.request({
    method: 'PUT',
    hostname: hostname,
    port: port,
    path: path,
    headers: {
      'Authorization': 'Basic ' + auth,
      'Content-Type': 'text/markdown',
      'Content-Length': Buffer.byteLength(body)
    }
  }, (res) => {
    let buf = '';
    res.on('data', c => buf += c);
    res.on('end', () => {
      const ok = res.statusCode >= 200 && res.statusCode < 300;
      resolve([{ json: { ...p, nextcloudUploaded: ok, nextcloudStatus: res.statusCode, nextcloudTarget: target, nextcloudOutput: buf.trim() } }]);
    });
  });
  req.on('error', (e) => resolve([{ json: { ...p, nextcloudUploaded: false, nextcloudError: String(e.message || e), nextcloudTarget: target } }]));
  req.setTimeout(20000, () => { req.destroy(); resolve([{ json: { ...p, nextcloudUploaded: false, nextcloudError: 'timeout', nextcloudTarget: target } }]); });
  req.write(body);
  req.end();
});

// Registrar el resultado en el log de informes (leer desde nodo Guardar, no desde Email SMTP)
const fs = require('fs');
const p = $('Guardar Informe Local (.md)').all()[0].json;
const line = '[' + new Date().toISOString() + '] INFORME: ' + p.filename + ' | riesgo=' + (p.analysis && p.analysis.riskLevel) + ' | anomalias=' + ((p.analysis && p.analysis.anomalies) || []).length + ' | filepath=' + p.filepath + '\n';
try { fs.appendFileSync('/data/informes/informes-log.txt', line, 'utf8'); return [{ json: Object.assign({}, p, { logWritten: true }) }]; }
catch (e) { return [{ json: Object.assign({}, p, { logError: String(e.message || e) }) }]; }
